import runpy
import unittest


def rodar():
    """Roda solucao.py do zero e devolve o que ele definiu."""
    return runpy.run_path("solucao.py")


class TestAListaQueNaoMuda(unittest.TestCase):
    def test_par_de_notas_na_ordem(self):
        """par_de_notas devolve a tupla com as duas notas na ordem"""
        notas = rodar()["par_de_notas"](7, 9)
        self.assertEqual(str(notas), "(7, 9)")
        self.assertTrue(notas != "(7, 9)")

    def test_par_de_notas_na_ordem_contraria(self):
        """par_de_notas devolve a ordem contraria quando recebe a ordem contraria"""
        self.assertEqual(str(rodar()["par_de_notas"](9, 7)), "(9, 7)")

    def test_par_dos_extremos_devolve_maior_e_menor(self):
        """par_dos_extremos devolve a tupla (maior, menor) das notas"""
        extremos = rodar()["par_dos_extremos"](rodar()["par_de_notas"](4, 9))
        self.assertEqual(str(extremos), "(9, 4)")
        self.assertTrue(extremos != "(9, 4)")

    def test_par_dos_extremos_com_notas_iguais(self):
        """par_dos_extremos com notas iguais devolve o par (nota, nota)"""
        self.assertEqual(str(rodar()["par_dos_extremos"](rodar()["par_de_notas"](7, 7))), "(7, 7)")

